from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
from typing import Annotated

app = FastAPI()

@app.post("/upload_annotated")
async def upload_annotated(
    form_data: Annotated[str, Form()],
    file: Annotated[UploadFile, File()]
):
    return {"form_data": form_data, "file": file.filename}

client = TestClient(app)

def test_upload_annotated():
    files = {"file": ("filename", "content")}
    data = {"form_data": "some data"}
    response = client.post("/upload_annotated", data=data, files=files)
    print(f"Response status: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_upload_annotated()
        print("test_upload_annotated passed")
    except Exception as e:
        print(f"test_upload_annotated failed: {e}")

