import functools
from typing import ForwardRef, Any, Callable
import inspect
from fastapi.dependencies.utils import get_typed_signature

class B:
    pass

def wrapper(func: Callable[..., Any]) -> Callable[..., Any]:
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def my_endpoint(x: "B"):
    return x

# Wrap the endpoint
wrapped_endpoint = wrapper(my_endpoint)

try:
    print("Testing get_typed_signature with wrapped function and forward reference...")
    sig = get_typed_signature(wrapped_endpoint)
    print("Successfully got signature:", sig)
    for param in sig.parameters.values():
        print(f"Param {param.name}: {param.annotation}")
except NameError as e:
    print(f"Caught NameError: {e}")
except Exception as e:
    print(f"Caught exception: {type(e).__name__}: {e}")
    import traceback
    traceback.print_exc()

