from fastapi import FastAPI
from pydantic import BaseModel, Field
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

class ModelWithRef(BaseModel):
    ref: str = Field(alias="$ref")

@app.get("/")
def read_root():
    return {"hello": "world"}

@app.post("/test")
def test_endpoint(item: ModelWithRef):
    return item

client = TestClient(app)

def test_ref_field():
    # This should not crash when generating the OpenAPI schema
    # The crash happens during the internal processing of the schema in fastapi/_compat/v2.py
    # which is called when accessing app.openapi()
    try:
        app.openapi()
        print("OpenAPI schema generated successfully")
    except Exception as e:
        print(f"Caught exception: {e}")
        raise e

if __name__ == "__main__":
    test_ref_field()

