from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, computed_field

app = FastAPI(separate_input_output_schemas=False)

class Item(BaseModel):
    name: str
    price: float

    @computed_field
    @property
    def total_price(self) -> float:
        return self.price * 1.2

@app.get("/item", response_model=Item)
def get_item():
    return Item(name="Test", price=10.0)

client = TestClient(app)

def test_computed_field_in_schema():
    response = client.get("/openapi.json")
    schema = response.json()

    # Find the Item schema
    item_schema = None
    for name, schema_def in schema["components"]["schemas"].items():
        if "Item" in name:
            item_schema = schema_def
            break

    assert item_schema is not None, "Item schema not found"
    assert "total_price" in item_schema["properties"], f"total_price missing from Item schema: {item_schema}"

if __name__ == "__main__":
    try:
        test_computed_field_in_schema()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

